function setActiveCandidate(index){const input=document.querySelector('[data-cx-place-input]'),box=document.querySelector('[data-cx-place-results]'),buttons=[...box?.querySelectorAll('[data-cx-place-option]')||[]];if(!buttons.length){input?.removeAttribute('aria-activedescendant');activeCandidateIndex=-1;return}activeCandidateIndex=(index+buttons.length)%buttons.length;buttons.forEach((button,i)=>button.setAttribute('aria-selected',String(i===activeCandidateIndex)));const active=buttons[activeCandidateIndex];input?.setAttribute('aria-activedescendant',active.id);active?.scrollIntoView({block:'nearest'})}
