async function selectCandidate(candidate){selectedCandidate=candidate;visibleCandidates=[];const input=document.querySelector('[data-cx-place-input]'),box=document.querySelector('[data-cx-place-results]'),spinner=document.querySelector('[data-cx-place-spinner]');if(input)input.value=candidate.primaryLabel||candidate.label;if(box)box.hidden=true;setPlaceExpanded(false);if(spinner)spinner.hidden=false;try{const form=document.querySelector('[data-cx-personal-form]');const payload=await requestJson('/api/location-resolve',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({providerRef:candidate.providerRef,birthDate:form?.elements.birthDate?.value||null,birthTime:form?.elements.birthTimeUnknown?.checked?null:(form?.elements.birthTime?.value||null),locale:locale()})});place=payload.location;birthLocationSnapshot=payload.birthLocationSnapshot||null;const confirmed=document.querySelector('[data-cx-place-confirmed]'),label=document.querySelector('[data-cx-place-confirmed-label]');if(label)label.textContent=place.customerLabel||place.displayName;if(confirmed)confirmed.hidden=false}catch{clearPlace({keepText:true});setStatus(document.querySelector('[data-cx-personal-status]'),tr('We found the place name but could not confirm its location details. Please choose it again in a moment.','已经找到地点名称，但暂时无法确认坐标与时区。请稍后再选择一次。'),'error')}finally{if(spinner)spinner.hidden=true}}
async function searchPlaces(q){const box=document.querySelector('[data-cx-place-results]'),spinner=document.querySelector('[data-cx-place-spinner]');const seq=++searchSeq;if(q.trim().length<2){if(box)box.hidden=true;setPlaceExpanded(false);return}if(spinner)spinner.hidden=false;try{const payload=await requestJson(`/api/location-search?q=${encodeURIComponent(q.trim())}&locale=${encodeURIComponent(locale())}`);if(seq!==searchSeq)return;renderCandidates(arr(payload.candidates))}catch{if(seq!==searchSeq)return;if(box){box.innerHTML=`<div class="cx-p1-empty">${esc(tr('Place search is temporarily unavailable. Please try again shortly.','地点搜索暂时无法使用，请稍后再试。'))}</div>`;box.hidden=false;setPlaceExpanded(true)}}finally{if(seq===searchSeq&&spinner)spinner.hidden=true}}
