async function runExternalProfileShadowCheck(form){if(!confirmedExternalProfile||!form?.elements.externalProfileShadowCheck?.checked)return null;const fd=new FormData(form);const payload=await requestJson('/api/customer-external-profile-shadow-check',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({confirmedExternalProfile,birthDate:fd.get('birthDate')||null,birthTime:fd.get('birthTimeUnknown')?null:(fd.get('birthTime')||null),placeRef:selectedCandidate?.providerRef||null,locale:locale(),consent:true})});externalProfileShadowValidation=payload.shadowValidation||null;const node=document.querySelector('[data-cx-external-profile-shadow-result]');if(node){node.hidden=false;const state=externalProfileShadowValidation?.state;if(state==='REFERENCE_MATCH')node.innerHTML=`<strong>${esc(tr('Internal consistency check: no compared differences found','内部一致性检查：已比较项目未发现差异'))}</strong><p>${esc(tr('This internal check does not replace the profile you confirmed and does not create a PHI OS Human Design result.','这项内部检查不会替换你确认的资料，也不会生成 PHI OS 对外的人类图结果。'))}</p>`;else if(state==='PROFILE_DISCREPANCY'){const mismatches=arr(externalProfileShadowValidation?.comparisons).filter(item=>item.status==='MISMATCH');node.innerHTML=`<strong>${esc(tr('Some details differ from the internal reference check','部分资料与内部参考检查不同'))}</strong><p>${esc(tr('Your confirmed upload remains the authority. Review the original report or birth details if you want to resolve the difference.','你确认的上传资料仍然是外部资料权威。如需处理差异，可以重新核对原报告或出生资料。'))}</p>${mismatches.length?`<ul>${mismatches.map(item=>`<li>${esc(item.field)}</li>`).join('')}</ul>`:''}`;}else node.innerHTML=`<strong>${esc(tr('Internal consistency check not run','内部一致性检查未运行'))}</strong><p>${esc(tr('Exact birth time and a confirmed place are needed for this optional check, or the internal validation runtime may be unavailable.','这项可选检查需要精确出生时间与已确认地点；内部验证 runtime 暂时不可用时也会保持未运行。'))}</p>`}return externalProfileShadowValidation}
