function externalProfileInputPresent(form){const file=form?.elements.externalProfileFile?.files?.[0]||null,text=form?.elements.externalProfileText?.value?.trim()||'';const names=['manualType','manualStrategy','manualAuthority','manualProfile','manualDefinition','manualIncarnationCross','manualSignature','manualNotSelfTheme','manualChannels','manualDefinedCenters','manualOpenCenters','manualDesignActivations','manualPersonalityActivations','externalVariable','externalCognition','externalDetermination','externalEnvironment','externalPerspective','externalMotivation','externalTrajectory'];return Boolean(file||text||names.some(name=>form?.elements[name]?.value?.trim()))}
